pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 collectAmount, uint256 minSum, uint256 attackMinSum) public {
        // Bound to reasonable ranges to keep search wide but avoid overflow
        lockTime = bound(lockTime, 0, uint256(type(uint64).max));
        collectAmount = bound(collectAmount, 1, 1e36);
        minSum = bound(minSum, 0, 1e36);
        attackMinSum = bound(attackMinSum, 0, type(uint256).max);

        // Setup: initialize contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(this));
        c.Initialized();

        // Attacker deposits funds
        address attacker = address(0xBAD);
        vm.deal(attacker, collectAmount);
        vm.prank(attacker);
        c.Put{value: collectAmount}(lockTime);

        // Warp to after unlockTime
        uint256 unlockTime = block.timestamp + lockTime;
        vm.warp(unlockTime + 1);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Malicious contract that will re-enter via Collect and call SetMinSum
        // We simulate this by deploying a helper contract
        ReenterAttacker reenter = new ReenterAttacker(address(c), attackMinSum);
        vm.deal(address(reenter), collectAmount);
        reenter.deposit(collectAmount);
        vm.warp(unlockTime + 2);

        reenter.attack(collectAmount);

        // MinSum after the attack
        uint256 minSumAfter = c.MinSum();

        // Assertion: MinSum never changes due to a Collect call (only changeable via SetMinSum directly)
        assertEq(minSumAfter, minSumBefore);
    }
}

contract ReenterAttacker {
    C target;
    uint256 attackMinSum;
    bool entered;
    constructor(address _target, uint256 _attackMinSum) {
        target = C(payable(_target));
        attackMinSum = _attackMinSum;
    }
    function deposit(uint256 amount) payable public {
        target.Put{value: amount}(0);
    }
    function attack(uint256 amount) external {
        target.Collect(amount);
    }
    fallback() external payable {
        if (!entered && msg.sender == address(target)) {
            entered = true;
            target.SetMinSum(attackMinSum);
        }
    }
}

