contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amt, uint256 lockTime, uint256 minSumInit, uint256 attackerAmt) public {
        // amt and attackerAmt are amounts for Collect; lockTime for Put; minSumInit to set MinSum
        vm.assume(minSumInit <= type(uint256).max);
        vm.assume(amt <= type(uint256).max);
        vm.assume(lockTime <= type(uint192).max);
        vm.assume(attackerAmt <= type(uint256).max);
        // setup: initialize contract
        c.Initialized();
        c.SetMinSum(minSumInit);
        // fund and put for a user
        address user = makeAddr("user");
        vm.deal(user, amt + 1 ether);
        vm.startPrank(user);
        c.Put{value: amt + 1 ether}(lockTime);
        vm.stopPrank();
        // warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);
        // record MinSum before Collect
        uint256 msBefore = c.MinSum();
        // call Collect that should not revert under correct behavior
        bool ok;
        vm.prank(user);
        try c.Collect(amt) { ok = true; } catch { ok = false; }
        // If Collect succeeded, MinSum must remain exactly as before the call
        if (ok) {
            assertEq(c.MinSum(), msBefore);
        } else {
            // If it reverted, invariant is vacuously true (no state change visible)
