pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 depositAmount, uint256 collectAmount, uint256 newMinSum) public {
        // Keep values within reasonable bounds
        bound(lockTime, 0, type(uint128).max);
        bound(depositAmount, 1, type(uint128).max);
        bound(collectAmount, 1, type(uint128).max);
        bound(newMinSum, 1, type(uint256).max);

        // Setup: Initialize contract and set MinSum, then make a deposit for actor
        address actor = address(0x1000);
        vm.prank(address(this));
        c.SetMinSum(1);
        vm.prank(address(this));
        c.SetLogFile(address(0x2000));
        vm.prank(address(this));
        c.Initialized();

        // Record the current MinSum before the actor's operations
        uint256 minSumBefore = c.MinSum();

        // Actor deposits funds
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(lockTime);

        // Warp past unlock time to make funds available
        vm.warp(block.timestamp + lockTime + 1);

        // The attacker contract that performs reentrancy by calling Collect, then in its fallback calling SetMinSum with newMinSum
        address attackerContract = address(new Attacker(address(c), newMinSum, collectAmount));
        vm.deal(attackerContract, collectAmount);

        // Attacker deposits to have a balance
        vm.prank(attackerContract);
        c.Put{value: collectAmount}(0);

        // Warp again to ensure unlock
        vm.warp(block.timestamp + 1);

        // Attacker calls Collect which will trigger reentrancy
        uint256 minSumBeforeCollect = c.MinSum();
        vm.prank(attackerContract);
        c.Collect(collectAmount);

        // After Collect, MinSum must remain what it was before the call
        // In the reference, nonReentrant_ modifier prevents reentrancy, so SetMinSum cannot be called during Collect.
        // In the buggy version, the modifier allows reentrancy, so the attacker's fallback calls SetMinSum and changes MinSum.
        assertEq(c.MinSum(), minSumBeforeCollect);
    }
}

contract Attacker {
    C target;
    uint256 newMinSum;
    uint256 collectAmount;
    bool reentered;

    constructor(address _target, uint256 _newMinSum, uint256 _collectAmount) {
        target = C(_target);
        newMinSum = _newMinSum;
        collectAmount = _collectAmount;
        reentered = false;
    }

    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // Reenter by changing MinSum through SetMinSum
            target.SetMinSum(newMinSum);
        }
    }
}

