import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amt, uint256 lockTime) public {
        // amt must be positive so collect can actually proceed
        vm.assume(amt > 0);
        // lockTime must not overflow when added to block.timestamp
        vm.assume(lockTime <= type(uint256).max - block.timestamp);
        // We also need c to have enough ether to pay out
        // We'll fund c directly via Put, or by deploying with a deposit
        // Deploy an attacker contract that calls SetMinSum on collect
        // The attacker will receive the collect call and re-enter
        // Initialization: set MinSum to something non-zero
        address attacker = address(new Attacker(address(this), address(c)));
        vm.deal(attacker, 0);
        vm.startPrank(attacker);
        c.Put{value: amt}(lockTime);
        vm.stopPrank();
        // Set MinSum to amt via c's owner (this test contract is not owner, SetMinSum is permissionless but guarded)
        // Actually SetMinSum is public, so anyone can call it (nonReentrant)
        vm.prank(address(this));
        c.SetMinSum(amt);
        // Now call collect through attacker
        vm.prank(attacker);
        // The attacker's receive re-enters SetMinSum to change MinSum
        Attacker(attacker).attack(amt);
        // After the call, MinSum must remain amt if lock worked; bug allows reentrant SetMinSum to change it
        assertEq(c.MinSum(), amt);
    }
}

