import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 firstVal, uint256 secondVal, address attacker) public {
        vm.assume(attacker != address(0) && attacker != address(c));
        vm.assume(firstVal != secondVal);

        // Deploy a reentrant attacker contract that calls SetMinSum again
        ReentrantAttacker re = new ReentrantAttacker(c, firstVal, secondVal);
        vm.deal(address(re), 1 ether);

        bool referenceRevert = false;
        try re.attack() {
            referenceRevert = false;
        } catch {
            referenceRevert = true;
        }

        // In the reference contract, MinSum should be unchanged because the reentrant call must revert
        // In the buggy contract, the reentrant call succeeds and MinSum becomes secondVal
        assertTrue(referenceRevert && c.MinSum() == firstVal || !referenceRevert && c.MinSum() == secondVal);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 first;
    uint256 second;
    bool reentered;

    constructor(C _target, uint256 _first, uint256 _second) {
        target = _target;
        first = _first;
        second = _second;
    }

    function attack() external {
        target.SetMinSum(first);
    }

    fallback() external payable {
        if (!reentered) {
            reentered = true;
            target.SetMinSum(second);
        }
    }
}
